import{_ as a,o,c as r,a2 as t}from"./chunks/framework.CiKk3sJz.js";const m=JSON.parse('{"title":"漫画 · 第 9 话 Transform：不惊动文档流的几何魔法","description":"","frontmatter":{},"headers":[],"relativePath":"comics/css/EP.09-transform.md","filePath":"comics/css/EP.09-transform.md","lastUpdated":1792579602000}'),s={name:"comics/css/EP.09-transform.md"};function d(c,e,l,i,n,h){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="漫画-·-第-9-话-transform-不惊动文档流的几何魔法" tabindex="-1">漫画 · 第 9 话 Transform：不惊动文档流的几何魔法 <a class="header-anchor" href="#漫画-·-第-9-话-transform-不惊动文档流的几何魔法" aria-label="Permalink to &quot;漫画 · 第 9 话 Transform：不惊动文档流的几何魔法&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/css/09-transform">docs/css/09-transform.md</a> ｜ 原画：<a href="./EP.09-transform.svg">EP.09-transform.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。用 <code>left</code> 写位移动画，长列表一滑动就掉帧，被码叔一句&quot;你每帧都在重排&quot;点醒。</li><li><strong>标签君</strong>：HTML5 结构师，画出两条变换链的矩阵差异，并协助拼装 3D 翻转卡的三层结构。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p><code>transform</code> 是唯一&quot;不惊动文档流&quot;的几何工具：位移、旋转、缩放、倾斜都只作用在最终绘制结果上，元素的布局盒纹丝不动。像素酱先搞懂为什么 <code>transform</code> 动画只走合成器，再弄清函数顺序为什么影响结果，最后用 perspective → preserve-3d → backface-visibility 三件套搭出一张会翻面的卡片。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>动画 <code>left: 0 → 200px</code> 时，浏览器每一帧都要重走 Layout → Paint → Composite 整条流水线；而动画 <code>transform: translateX(200px)</code> 时，元素被提升为合成层，位移只是合成器线程上的一次矩阵更新，主线程即使卡住动画依然流畅。性能优化第一课：<code>left</code> 换 <code>translateX</code>，<code>width</code> 换 <code>scaleX</code>。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>每个变换函数都对应一个矩阵，浏览器把函数序列<strong>从左到右依次相乘</strong>。矩阵乘法不可交换：先 <code>translateX(80px)</code> 再 <code>rotate(45deg)</code>，是沿原 X 轴走完再原地转；先旋转再平移，X 轴已经被带斜，元素会沿斜向推出。<code>transform-origin</code> 是旋转与缩放的基准点（默认盒子中心），而 <code>translate</code> 的百分比基于<strong>自身</strong>尺寸——这正是 <code>left:50% + translate(-50%,-50%)</code> 无宽高精确居中的原理。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>3D 翻转卡需要三层各司其职：<strong>舞台</strong>（父元素）写 <code>perspective: 900px</code> 提供近大远小，全部子面共享一个灭点；<strong>中间层</strong>写 <code>transform-style: preserve-3d</code>，否则默认 <code>flat</code> 会把正反两面拍扁叠在一起；<strong>每个面</strong>写 <code>backface-visibility: hidden</code>，背面预翻 <code>rotateY(180deg)</code>，悬停时中间层整体转 180°，正面隐去、背面显现。注意 <code>overflow:hidden</code>、<code>filter</code>、<code>opacity&lt;1</code> 会强制打平 preserve-3d——3D 失效先查祖先链上的这批属性。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>transform 不碰文档流：位移后元素仍占原位，动画只走合成器，主线程卡顿也不掉帧。</li><li>函数从左到右依次相乘、顺序敏感；拼 3D 口诀是&quot;先转正、再推出&quot;。</li><li>三件套：父 perspective、中 preserve-3d、面 backface-visibility:hidden；overflow:hidden 会打平 3D。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：为什么 <code>rotate(45deg) translateX(80px)</code> 和 <code>translateX(80px) rotate(45deg)</code> 的最终位置不一样？</p><p><strong>答</strong>：变换函数从左到右依次应用，且每个函数都在&quot;当前坐标系&quot;里生效。先旋转后，元素自身的 X 轴已经倾斜 45°，此时 <code>translateX(80px)</code> 是沿斜向推出；先平移时 X 轴还是水平的。本质是矩阵乘法不可交换：A·B ≠ B·A。排查复合变换可用 <code>getComputedStyle(el).transform</code> 读最终矩阵逐项核对。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>2D 变换实验台：translate/rotate/scale/skew + matrix 对照 + transform-origin：<a href="./../../examples/css/09-transform/index-01-2d-transforms.html">examples/css/09-transform/index-01-2d-transforms.html</a></li><li>3D 翻转卡片：perspective / preserve-3d / backface-visibility 全流程：<a href="./../../examples/css/09-transform/index-02-3d-flip-card.html">index-02-3d-flip-card.html</a></li><li>3D 立方体 + 轮播 + translateZ 层深视差：<a href="./../../examples/css/09-transform/index-03-3d-cube-carousel.html">index-03-3d-cube-carousel.html</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 10 话《文本截断》——长 URL 撑爆 flex 行、省略号死活不出现？三件套与 <code>min-width:0</code> 前来救场。</p>',22)])])}const p=a(s,[["render",d]]);export{m as __pageData,p as default};
